{"command": "cat > /workdir/solve.py << 'PYEOF'
import json
import re
import sqlite3
import os

# Read the raw files
with open('/workdir/data/books.json', 'r') as f:
    books_raw = f.read()

with open('/workdir/data/book_prices.json', 'r') as f:
    prices_raw = f.read()

def parse_books_raw(text):
    """Parse books.json manually - find all book objects containing title, author, year, genre, pages"""
    books = []
    # Find all matches of book objects by finding "title" entries and capturing the whole object
    # Let's find all positions where "title" appears and extract from that point until next "title"
    # Or use regex that captures each complete book object

    # Strategy: Split the text by looking for each book object starting with {"title":
    # Actually, let's find all occurrences of the pattern that starts a book object:
    # {"title": or { "title":
    # Then extract until the next {"title": or end of file

    # Simpler: Use regex to find each book object block that contains title, author, year, genre, pages
    # The block can span multiple lines
    # Let me find all matches using a pattern that captures everything between one "title" and the next

    # Actually, let me use a state machine approach that properly tracks fields
    lines = text.split('\n')
    current_book = {}
    in_book = False  # True when we've seen "title" and are collecting its object

    for line in lines:
        line_stripped = line.rstrip()
        if '"title":' in line_stripped:
            # Save previous book if any
            if in_book and current_book:
                books.append(current_book)
                current_book = {}
            # Parse title from this line
            match = re.match(r'"title":\s*"([^"]*)"', line_stripped)
            if match:
                current_book['title'] = match.group(1)
            in_book = True
            # Reset other fields
            current_book.clear()  # but we already set title... let me adjust
            # Actually better: when starting new book, clear it then set title
            current_book = {}
            match = re.match(r'"title":\s*"([^"]*)"', line_stripped)
            if match:
                current_book['title'] = match.group(1)
            in_book = True
        elif in_book:
            # We're collecting fields for current book
            if '"author":' in line_stripped:
                match = re.match(r'"author":\s*"([^"]*)"', line_stripped)
                if match:
                    current_book['author'] = match.group(1)
            elif '"year":' in line_stripped:
                match = re.match(r'"year":\s*(\d+)', line_stripped) or re.match(r'"year":\s*"(\d+)"', line_stripped)
                if match:
                    year_val = match.group(1)
                    current_book['year'] = int(year_val)
            elif '"genre":' in line_stripped:
                match = re.match(r'"genre":\s*"([^"]*)"', line_stripped)
                if match:
                    current_book['genre'] = match.group(1)
            elif '"pages":' in line_stripped:
                match = re.match(r'"pages":\s*(\d+)', line_stripped) or re.match(r'"pages":\s*"(\d+)"', line_stripped)
                if match:
                    pages_val = match.group(1)
                    current_book['pages'] = int(pages_val)
            # Check for closing brace
            if line_stripped.strip() == '}':
                in_book = False
                books.append(current_book.copy())
                current_book = {}
    # Handle last book
    if in_book and current_book:
        books.append(current_book.copy())
    return books

def parse_prices_raw(text):
    """Parse book_prices.json manually"""
    prices = []
    lines = text.split('\n')
    current_price = {}
    in_price = False
    for line in lines:
        line_stripped = line.rstrip()
        if '"title":' in line_stripped:
            if in_price and current_price:
                prices.append(current_price)
                current_price = {}
            match = re.match(r'"title":\s*"([^"]*)"', line_stripped)
            if match:
                current_price['title'] = match.group(1)
            in_price = True
            current_price = {}
            match = re.match(r'"title":\s*"([^"]*)"', line_stripped)
            if match:
                current_price['title'] = match.group(1)
            in_price = True
        elif in_price:
            if '"price":' in line_stripped:
                match = re.match(r'"price":\s*([\d.]+)', line_stripped)
                if match:
                    current_price['price'] = float(match.group(1))
            if line_stripped.strip() == '}':
                in_price = False
                prices.append(current_price.copy())
                current_price = {}
    if in_price and current_price:
        prices.append(current_price.copy())
    return prices

# Test parsing
books_list = parse_books_raw(books_raw)
print("Parsed books count:", len(books_list))
for b in books_list:
    print(b)
print("---")
prices_list = parse_prices_raw(prices_raw)
print("Parsed prices count:", len(prices_list))
for p in prices_list:
    print(p)
