{"command": "cat > /workdir/solve.py << 'PYEOF'
import json
import re
import sqlite3
import os

# Read the raw files
with open('/workdir/data/books.json', 'r') as f:
    books_raw = f.read()

with open('/workdir/data/book_prices.json', 'r') as f:
    prices_raw = f.read()

def extract_books(text):
    books = []
    lines = text.split('\n')
    current_lines = []
    for line in lines:
        if '"title":' in line or "'title':" in line:
            if current_lines:
                block = '\n'.join(current_lines)
                books.append(parse_book_block(block))
                current_lines = []
            current_lines.append(line)
        else:
            current_lines.append(line)
    if current_lines:
        block = '\n'.join(current_lines)
        books.append(parse_book_block(block))
    return books

def parse_book_block(text):
    result = {}
    # Extract title - handle both "title": "val" and "title": 'val'
    m = re.search(r'"title":\s*["\']([^"\']*)["\']', text)
    if m:
        result['title'] = m.group(1)

    # Extract author
    m = re.search(r'"author":\s*["\']([^"\']*)["\']', text)
    if m:
        result['author'] = m.group(1)

    # Extract year
    m = re.search(r'"year":\s*(\d+)', text)
    if m:
        result['year'] = int(m.group(1))
    else:
        m = re.search(r'"year":\s*"(\d+)"', text)
        if m:
            result['year'] = int(m.group(1))

    # Extract genre
    m = re.search(r'"genre":\s*["\']([^"\']*)["\']', text)
    if m:
        result['genre'] = m.group(1)

    # Extract pages
    m = re.search(r'"pages":\s*(\d+)', text)
    if m:
        result['pages'] = int(m.group(1))
    else:
        m = re.search(r'"pages":\s*"(\d+)"', text)
        if m:
            result['pages'] = int(m.group(1))

    return result

def parse_price_block(text):
    result = {}
    m = re.search(r'"title":\s*["\']([^"\']*)["\']', text)
    if m:
        result['title'] = m.group(1)
    m = re.search(r'"price":\s*([\d.]+)', text)
    if m:
        result['price'] = float(m.group(1))
    return result

def extract_prices(text):
    prices = []
    lines = text.split('\n')
    current_lines = []
    for line in lines:
        if '"title":' in line:
            if current_lines:
                block = '\n'.join(current_lines)
                prices.append(parse_price_block(block))
                current_lines = []
            current_lines.append(line)
        else:
            current_lines.append(line)
    if current_lines:
        block = '\n'.join(current_lines)
        prices.append(parse_price_block(block))
    return prices

# Parse everything
books_list = extract_books(books_raw)
prices_list = extract_prices(prices_raw)

print("Books count:", len(books_list))
for b in books_list[:5]:
    print(b)
print("...")
print("Prices count:", len(prices_list))
for p in prices_list[:5]:
    print(p)
